using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class Scene3MaterialReview {
 static double when;static Scene3MaterialReview(){when=EditorApplication.timeSinceStartup+8;EditorApplication.update+=Tick;}
 static void Tick(){if(EditorApplication.timeSinceStartup<when||EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists("D:/-11-scene3-audit/transfer-result.json"))return;if(File.Exists("D:/-11-scene3-audit/material-review.txt"))return;EditorApplication.update-=Tick;Run();}
 static void Run(){try{var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;var root=s.GetRootGameObjects().First(g=>g.name=="CompanySource");var lines=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials.Select((m,i)=>r.name+"|"+i+"|"+(m?m.name:"NULL")+"|shader="+(m?m.shader.name:"")+"|base="+(m&&m.HasProperty("_MainTex")&&m.GetTexture("_MainTex")?AssetDatabase.GetAssetPath(m.GetTexture("_MainTex")):"constant")+"|normal="+(m&&m.HasProperty("_BumpMap")&&m.GetTexture("_BumpMap")?AssetDatabase.GetAssetPath(m.GetTexture("_BumpMap")):"none"))).ToArray();File.WriteAllLines("D:/-11-scene3-audit/material-review.txt",lines);
 var go=new GameObject("Temporary material inspection camera"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();var src=root.GetComponentInChildren<Camera>();if(src)cam.CopyFrom(src);cam.enabled=false;cam.transform.position=new Vector3(0,1.25f,0.1f);cam.transform.LookAt(new Vector3(0,1,-3));cam.fieldOfView=75;cam.nearClipPlane=.02f;cam.allowHDR=true;var view=go.AddComponent<Scene3ColorView>();view.viewShader=Shader.Find("BlenderScene3/ColorView");var rt=RenderTexture.GetTemporary(1200,800,24,RenderTextureFormat.ARGBHalf);var active=RenderTexture.active;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var im=new Texture2D(1200,800,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,1200,800),0,0);if(!rt.sRGB){var pixels=im.GetPixels();for(int k=0;k<pixels.Length;k++)pixels[k]=pixels[k].gamma;im.SetPixels(pixels);}im.Apply();File.WriteAllBytes("D:/-11-scene3-audit/interior-after.png",im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}finally{RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}var sv=SceneView.lastActiveSceneView;if(sv){sv.sceneLighting=true;sv.sceneViewState.showImageEffects=true;sv.Repaint();}
 }catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/material-review-error.txt",e.ToString());}}
}

